from fastapi import FastAPI, HTTPException
from pydantic import BaseModel

app = FastAPI()

class Item(BaseModel):
    name: str
    price: float
    is_offer: bool = None

items = {}

@app.get("/items/{item_id}")
async def read_item(item_id: int, q: str = None):
    if item_id not in items:
        raise HTTPException(status_code=404, detail="Item not found")
    return {"item_name": items[item_id].name, "item_id": item_id}

# Example usage:
# items[1] = Item(name="The Foo Wrestlers", price=100.0)
# Now, requesting /items/1 will return {"item_name": "The Foo Wrestlers", "item_id": 1}
# Requesting /items/bar (non-existent item_id) will raise a 404 error
